                  <a class="button-link button--ghost" href="#editorial">Read the latest stories</a>
                </div>
                <ul class="stat-list" aria-label="Store highlights">
                  <li class="stat-card"><strong>120+</strong><span class="meta">new-season styles live now</span></li>
                  <li class="stat-card"><strong>48 hours</strong><span class="meta">for dispatch on core essentials</span></li>
                  <li class="stat-card"><strong>4.9 / 5</strong><span class="meta">average rating across best sellers</span></li>
                </ul>
              </div>
              ${HeroSpotlight()}
            </div>
          </section>
        `;
      }

      function ProductCard(product) {
        return `
          <li>
            <article class="product-card">
              <img src="${imageData(product.imageLabel, product.accentA, product.accentB)}" alt="${product.imageLabel}" />
              <div class="product-card__body">
                <p class="kicker">${product.category}</p>
                <h3><a href="/products/${slugify(product.name)}">${product.name}</a></h3>
                <p>${product.detail}</p>
                <div class="price-row">
                  <span class="price">${product.price}</span>
                  <span class="pill">${product.badge}</span>
                </div>
                <div class="card-actions">
                  <button class="button button--accent" type="button" data-action="add-to-bag" data-name="${product.name}" aria-label="Add to bag: ${product.name}">Add to bag</button>
                  <button class="button button--ghost" type="button" data-action="save" data-name="${product.name}" aria-label="Save: ${product.name}">Save</button>
                </div>
              </div>
            </article>
          </li>
        `;
      }

      function FeaturedSection() {
        return `
          <section class="section" id="featured" aria-labelledby="featured-heading">
            <div class="section__header">
              <div>
                <h2 id="featured-heading">Featured products</h2>
                <p>A focused edit of tactile knits, sharp accessories, and motion-ready footwear in a rich dark palette.</p>
              </div>
              <a class="button-link button--ghost" href="/collections/featured">View the full collection</a>
            </div>
            <ul class="product-grid">
              ${featuredProducts.map(ProductCard).join("")}
            </ul>
          </section>
        `;
      }

      function DealCard(deal) {
        return `
          <li>
            <article class="deal-card">
              <p class="deal-card__band">${deal.band}</p>
              <div class="deal-card__body">
                <h3>${deal.title}</h3>
                <p>${deal.copy}</p>
                <div class="deal-meta">
                  ${deal.meta.map((item) => `<span>${item}</span>`).join("")}
                </div>
                <p style="margin-top: 1.1rem;">
                  <a class="button-link" href="${deal.href}">Shop this deal</a>
                </p>
              </div>
            </article>
          </li>
        `;
      }

      function DealsSection() {
        return `
          <section class="section" id="deals" aria-labelledby="deals-heading">
            <div class="section__header">
              <div>
                <h2 id="deals-heading">Deals worth catching tonight</h2>
                <p>Short-window savings across wardrobe layers, performance bundles, and ambient home picks.</p>
              </div>
            </div>
            <ul class="deal-grid">
              ${deals.map(DealCard).join("")}
            </ul>
          </section>
        `;
      }

      function EditorialCard(story) {
        return `
          <li>
            <article class="editorial-card">
              <img src="${imageData(story.imageLabel, story.accentA, story.accentB)}" alt="${story.imageLabel}" />
              <div class="editorial-card__body">
                <p class="kicker">${story.kicker}</p>
                <h3>${story.title}</h3>
                <p>${story.copy}</p>
                <a class="button-link button--ghost" href="${story.href}">${story.linkText}</a>
              </div>
            </article>
          </li>
        `;
      }

      function EditorialSection() {
        return `
          <section class="section" id="editorial" aria-labelledby="editorial-heading">
            <div class="section__header">
              <div>
                <h2 id="editorial-heading">Editorial content</h2>
                <p>Stories, guides, and design notes that extend the retail experience beyond the cart.</p>
              </div>
            </div>
            <ul class="editorial-grid">
              ${editorialStories.map(EditorialCard).join("")}
            </ul>
          </section>
        `;
      }

      function Footer() {
        return `
          <footer class="footer">
            <div class="footer__grid">
              <div>
                <p class="kicker">Nightshift Supply</p>
                <small>Elevated essentials for evenings in motion and spaces with atmosphere.</small>
              </div>
              <nav class="footer__nav" id="footer-nav" aria-label="Footer">
                <ul>
                  <li><a href="/support/customer-care">Customer care</a></li>
                  <li><a href="/shipping">Shipping</a></li>
                  <li><a href="/returns">Returns</a></li>
                  <li><a href="/journal">Store journal</a></li>
                  <li><a href="https://www.instagram.com/nightshiftsupply/">Instagram</a></li>
                </ul>
              </nav>
            </div>
          </footer>
        `;
      }

      function Main() {
        return `
          <main id="maincontent" tabindex="-1">
            ${Hero()}
            <div class="container">
              ${FeaturedSection()}
              ${DealsSection()}
              ${EditorialSection()}
            </div>
          </main>
        `;
      }

      function App() {
        return `
          <div class="site-shell">
            ${Header()}
            ${Main()}
            ${Footer()}
            <div class="sr-only" aria-live="polite" aria-atomic="true" id="status-message"></div>
          </div>
        `;
      }

      function updateCartLabel() {
        const cartLink = document.getElementById("cart-link");
        if (cartLink) {
          cartLink.textContent = `Bag (${store.cartCount})`;
        }
      }

      function announce(message) {
        const status = document.getElementById("status-message");
        if (!status) return;
        status.textContent = "";
        window.setTimeout(() => {
          status.textContent = message;
        }, 20);
      }

      function attachEvents() {
        document.addEventListener("click", (event) => {
          const target = event.target;
          if (!(target instanceof HTMLElement)) return;

          const action = target.dataset.action;
          const name = target.dataset.name;

          if (action === "add-to-bag" && name) {
            store.cartCount += 1;
            updateCartLabel();
            announce(`${name} added to bag. Bag now contains ${store.cartCount} item${store.cartCount === 1 ? "" : "s"}.`);
          }

          if (action === "save" && name) {
            store.savedCount += 1;
            announce(`${name} saved for later. ${store.savedCount} item${store.savedCount === 1 ? "" : "s"} saved.`);
          }
        });

        const searchForm = document.getElementById("search-form");
        if (searchForm instanceof HTMLFormElement) {
          searchForm.addEventListener("submit", (event) => {
            event.preventDefault();
            const searchInput = document.getElementById("site-search");
            const query = searchInput instanceof HTMLInputElement ? searchInput.value.trim() : "";
            announce(query ? `Search preview for ${query}. Product discovery is shown on this home page.` : "Enter a search term to explore the collection.");
          });
        }
      }

      document.getElementById("app").innerHTML = App();
      updateCartLabel();
      attachEvents();
    </script>
  </body>
</html>
