        {
          title: "Studio sneaker bundle",
          copy: "Buy any pair of Vector Runners and add performance socks for 40% off.",
          band: "Online exclusive",
          meta: ["Automatic at checkout", "Sizes 5-13", "Ships in 24 hours"],
          href: "#featured",
        },
        {
          title: "Home refresh set",
          copy: "Bundle throws, candles, and ambient lighting to save $60 on your night-in lineup.",
          band: "Fresh markdown",
          meta: ["Curated sets", "Gift-ready packaging", "Low stock in amber glass"],
          href: "#editorial",
        },
      ];

      const editorialStories = [
        {
          kicker: "Editorial",
          title: "How to build a dark-tone capsule wardrobe",
          copy: "Explore five core layers, styling notes, and fabric pairings for a sleek weekday rotation.",
          linkText: "Read the capsule guide",
          href: "/journal/dark-tone-capsule-wardrobe",
          imageLabel: "Editorial collage of dark-tone wardrobe staples",
