            <rect width="800" height="600" rx="48" fill="#0b1020" />
            <circle cx="615" cy="150" r="120" fill="url(#g)" opacity="0.88" />
            <circle cx="230" cy="360" r="170" fill="${accentA}" opacity="0.4" />
            <rect x="120" y="120" width="500" height="320" rx="36" fill="none" stroke="${accentB}" stroke-width="8" opacity="0.75" />
            <text x="120" y="510" fill="#f4f7ff" font-family="Arial, Helvetica, sans-serif" font-size="34" font-weight="700">${label}</text>
