              <p>${spotlight.detail}</p>
              <a class="button-link" href="#featured">Explore the featured edit</a>
            </article>
          </aside>
        `;
      }

      function Hero() {
        return `
          <section class="hero" aria-labelledby="hero-heading">
            <div class="hero__panel">
              <div>
                <span class="eyebrow">After-hours essentials</span>
                <h1 id="hero-heading">Modern retail for the way your day winds down.</h1>
                <p>
                  Shop elevated layers, tactile footwear, and editorial picks designed for city evenings,
